<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { api } from '../api'
import CodexHandoffPanel from '../components/CodexHandoffPanel.vue'
import CatalogOzonTabs from '../components/CatalogOzonTabs.vue'
type Row={publication:any;store:any;key:string}
const codexBatch=ref('')
const checkedKeys=ref<string[]>([])
const reviewSignature=(row:Row)=>JSON.stringify(row.store.assets?.personal_review||{})
const checkedSignatures=new Map<string,string>()
function checkRow(row:Row,value:boolean){checkedKeys.value=checkedKeys.value.filter(key=>key!==row.key);if(value){checkedKeys.value.push(row.key);checkedSignatures.set(row.key,reviewSignature(row))}else checkedSignatures.delete(row.key)}
function checkAll(){for(const row of rows.value)checkRow(row,true)}
function clearChecked(){checkedKeys.value=[];checkedSignatures.clear()}
async function approveChecked(){if(processing.value)return;const targets=rows.value.filter(row=>checkedKeys.value.includes(row.key)).map(row=>({...row,signature:checkedSignatures.get(row.key)}));if(!targets.length)return;await ElMessageBox.confirm(`确认已逐项核验选中的 ${targets.length} 个店铺商品主图和附图，并批准？只继续准备资料，不会提交 Ozon。`,'批量核验确认',{type:'warning'});processing.value=true;let success=0;const errors:string[]=[];try{for(const row of targets){try{if(row.signature!==reviewSignature(row))throw new Error('候选图片已变化，请重新核验');await api.post(`/publications/${row.publication.id}/stores/${row.store.store_id}/image/approve`,{expected_review:row.store.assets?.personal_review||{}});success++;checkRow(row,false)}catch(error:any){errors.push(`${row.publication.sku} / ${row.store.store_name}：${error.message}`)}}ElMessage[errors.length?'warning':'success'](`已批准 ${success} 个${errors.length?`，${errors.length} 个未批准`:''}`);if(errors.length)await ElMessageBox.alert(errors.join('；'),'未批准项目');processing.value=false;await load(false)}finally{processing.value=false}}
const publications=ref<any[]>([]),loading=ref(false),processing=ref(false),selectedKey=ref(''),timer=ref<number>(),version=ref(0)
const rows=computed<Row[]>(()=>publications.value.flatMap(publication=>publication.stores.filter((store:any)=>store.status==='image_review').map((store:any)=>({publication,store,key:`${publication.id}:${store.store_id}`}))))
const selected=computed(()=>rows.value.find(row=>row.key===selectedKey.value)||rows.value[0])
const original=(row:Row)=>{const assets=Array.isArray(row.publication.product_snapshot?.assets)?row.publication.product_snapshot.assets:[];const main=assets.find((item:any)=>item.role==='main')||assets[0];return String(row.store.assets?.original_primary_image||main?.oss_url||row.store.assets?.primary_image||'')}
const candidate=(row:Row)=>`/api/v1/publications/${row.publication.id}/stores/${row.store.store_id}/image-preview?v=${version.value}`
let reading=false
async function load(show=true){if(processing.value||reading)return;reading=true;if(show)loading.value=true;try{const items:any[]=[];for(let page=1;page<=100;page++){const data=await api.get<any>(`/publications?page_size=200&page=${page}&store_status=image_review`);items.push(...(data.items||[]));if(items.length>=data.total||!data.items?.length)break}publications.value=items;checkedKeys.value=checkedKeys.value.filter(key=>rows.value.some(row=>row.key===key&&reviewSignature(row)===checkedSignatures.get(key)));if(!rows.value.some(row=>row.key===selectedKey.value))selectedKey.value=rows.value[0]?.key||''}finally{loading.value=false;reading=false}}
async function act(action:'approve'|'repair'|'redesign'|'full_redesign'){const row=selected.value;if(!row||processing.value)return;const labels={approve:'批准 AI 主图',repair:'修复当前图',redesign:'更换设计',full_redesign:'完全重做'};const descriptions={approve:`确认 ${row.publication.sku} 的 AI 主图与原商品一致？批准后进入待提交，不会立即提交 Ozon。`,repair:'保留当前构图，只修复商品、文字或画面问题。',redesign:'保留商品事实，更换场景、视角、配色和排版。',full_redesign:'只保留商品主体，不继承原海报或上一张候选图的设计。'};await ElMessageBox.confirm(descriptions[action],labels[action],{type:'warning'});processing.value=true;try{const result=await api.post<any>(`/publications/${row.publication.id}/stores/${row.store.store_id}/image/${action}`,action==='approve'?{expected_review:row.store.assets?.personal_review||{}}:{});if(action==='approve'){version.value++;ElMessage.success(result.job?'图片已批准，正在后台继续准备 Ozon 待提交资料':'审核通过，已进入后续准备');processing.value=false;await load(false)}else{if(result.codex_batch_id){codexBatch.value=result.codex_batch_id;ElMessage.success('已等待 Codex 重新处理图片')}else ElMessage.success('已创建后台生图任务，可在任务中心查看进度')}}finally{processing.value=false}}
onMounted(()=>{load();timer.value=window.setInterval(()=>load(false),5000)});onUnmounted(()=>clearInterval(timer.value))
</script>
<template><div class="page-stack review-page"><CatalogOzonTabs/><CodexHandoffPanel v-if="codexBatch" :batch-id="codexBatch"/><section class="panel review-shell"><header class="review-header"><div><div class="title-line"><h2>生图人工核验</h2><el-tag type="warning" size="large">待核验 {{rows.length}}</el-tag></div><p>逐 SKU、逐店铺对比；批准后进入待提交，不会立即创建 Ozon 商品。</p></div><div><el-button :disabled="processing" @click="checkAll">全选</el-button><el-button :disabled="processing" @click="clearChecked">清空勾选</el-button><el-button type="primary" :disabled="!checkedKeys.length" :loading="processing" @click="approveChecked">批量核验通过（{{checkedKeys.length}}）</el-button><el-button :loading="loading" @click="load()">刷新队列</el-button></div></header><div class="workspace" v-loading="loading"><aside class="queue"><div class="queue-title">待审核队列</div><div role="button" tabindex="0" v-for="(row,index) in rows" :key="row.key" class="queue-item" :class="{active:selected?.key===row.key}" @click="selectedKey=row.key"><el-checkbox :model-value="checkedKeys.includes(row.key)" :disabled="processing" @click.stop @change="(value:any)=>checkRow(row,Boolean(value))"/><img :src="candidate(row)"/><div><strong>{{row.publication.product_name||'未命名商品'}}</strong><span class="mono">{{row.publication.sku}}</span><small>{{row.store.store_name}}</small><small class="mono">{{row.store.offer_id}}</small></div><b>{{index+1}}</b></div><el-empty v-if="!loading&&!rows.length" description="当前没有待核验主图"/></aside><main v-if="selected" class="detail"><div class="toolbar"><div class="identity"><el-tag>{{selected.store.store_name}}</el-tag><div><h3>{{selected.publication.product_name}}</h3><p><b>SKU</b> <span class="mono">{{selected.publication.sku}}</span>　<b>Offer ID</b> <span class="mono">{{selected.store.offer_id}}</span></p></div></div><div class="actions"><el-button :loading="processing" @click="act('repair')">修复当前图</el-button><el-button :loading="processing" @click="act('redesign')">更换设计</el-button><el-button type="warning" plain :loading="processing" @click="act('full_redesign')">完全重做</el-button><el-button type="primary" size="large" :loading="processing" @click="act('approve')">确认一致并批准</el-button></div></div><div class="compare"><figure><figcaption><b>产品库原主图</b><span>事实参考，不会修改</span></figcaption><div class="stage"><el-image :src="original(selected)" fit="contain" :preview-src-list="[original(selected)]" preview-teleported/></div></figure><figure class="ai"><figcaption><b>AI 生成候选图</b><span>点击图片可全屏检查</span></figcaption><div class="stage"><el-image :src="candidate(selected)" fit="contain" :preview-src-list="[candidate(selected)]" preview-teleported/></div></figure></div><div v-if="selected.store.assets?.ai_preparation?.producer==='codex-desktop'" style="display:flex;gap:12px;flex-wrap:wrap;margin-top:16px"><figure v-for="(url,index) in selected.store.assets.ai_preparation.generated_additional_urls||[]" :key="url" style="margin:0;width:180px"><el-image :src="url" style="width:180px;height:240px" fit="contain" :preview-src-list="selected.store.assets.ai_preparation.generated_additional_urls" preview-teleported/><figcaption>Codex 附图 {{Number(index)+1}} · 一并核验</figcaption></figure></div><div class="hints"><b>核验重点</b><span>结构、颜色、数量、配件一致</span><span>俄文清晰且没有乱码</span><span>画面干净并适合 Ozon 主图</span></div></main><main v-else class="empty"><el-empty description="审核完成，当前没有待处理图片"/></main></div></section></div></template>
<style scoped>
.review-page{min-height:calc(100vh - 110px)}.review-shell{overflow:hidden}.review-header{display:flex;justify-content:space-between;align-items:center;padding:18px 22px;border-bottom:1px solid #e3eaf2}.title-line{display:flex;align-items:center;gap:12px}.title-line h2,.review-header p{margin:0}.review-header p{margin-top:5px;color:#6c7b90}.workspace{display:grid;grid-template-columns:330px minmax(0,1fr);min-height:720px}.queue{overflow-y:auto;max-height:calc(100vh - 235px);padding:12px;background:#f5f7fb;border-right:1px solid #dfe7f0}.queue-title{padding:5px 7px 12px;color:#607086;font-size:13px;font-weight:700}.queue-item{width:100%;display:grid;grid-template-columns:20px 72px minmax(0,1fr) 24px;gap:10px;align-items:center;margin-bottom:9px;padding:9px;border:1px solid #dce5ef;border-radius:10px;background:#fff;text-align:left;cursor:pointer}.queue-item:hover{border-color:#83aee8}.queue-item.active{border-color:#2168db;background:#edf5ff;box-shadow:0 0 0 2px #2168db1f}.queue-item img{width:72px;height:92px;object-fit:cover;border-radius:6px;background:#edf1f6}.queue-item>div{min-width:0;display:flex;flex-direction:column;gap:3px}.queue-item strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#173654}.queue-item span,.queue-item small{overflow-wrap:anywhere;color:#65758a}.queue-item>b{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;color:#fff;background:#91a2b8;font-size:11px}.queue-item.active>b{background:#2168db}.detail{min-width:0;padding:18px 22px 24px}.toolbar{position:sticky;top:0;z-index:3;display:flex;justify-content:space-between;align-items:center;gap:18px;margin:-18px -22px 18px;padding:15px 22px;border-bottom:1px solid #e4eaf1;background:#fff}.identity{display:flex;align-items:center;gap:12px;min-width:0}.identity h3,.identity p{margin:0}.identity h3{margin-bottom:5px;color:#173654}.identity p{color:#627187}.actions{display:flex;gap:10px;flex-shrink:0}.compare{display:grid;grid-template-columns:1fr 1fr;gap:18px}.compare figure{margin:0;overflow:hidden;border:1px solid #dce5ef;border-radius:12px;background:#fff}.compare figure.ai{border-color:#9abce9}.compare figcaption{display:flex;justify-content:space-between;padding:12px 15px;border-bottom:1px solid #e4eaf1;color:#26445f}.compare figcaption span{color:#7a899a;font-size:12px}.stage{height:min(66vh,760px);min-height:520px;padding:12px;background:#f1f3f6}.stage .el-image{width:100%;height:100%}.hints{display:flex;gap:18px;flex-wrap:wrap;margin-top:15px;padding:13px 16px;border-radius:9px;background:#fff8e8;color:#725b2d}.empty{display:grid;place-items:center}.mono{font-family:Consolas,monospace}@media(max-width:1100px){.workspace{grid-template-columns:260px minmax(0,1fr)}.compare{grid-template-columns:1fr}.stage{height:560px}.toolbar{align-items:flex-start;flex-direction:column}.actions{width:100%}}@media(max-width:720px){.workspace{display:block}.queue{max-height:310px;border-right:0;border-bottom:1px solid #dfe7f0}.detail{padding:14px}.toolbar{position:static;margin:-14px -14px 14px;padding:14px}.actions{display:grid;grid-template-columns:1fr 1fr}.stage{height:430px;min-height:0}.review-header{align-items:flex-start;gap:12px}.compare figcaption{align-items:flex-start;gap:5px;flex-direction:column}}
</style>
